package test;

import org.eclipse.core.resources.IContainer;
import org.eclipse.core.resources.ResourcesPlugin;
import org.eclipse.core.runtime.Path;

public class MyClass {
    public void processFile(String selectedFileName) {
        if (selectedFileName != null) {
            // Deprecated usage
            IContainer[] containers = ResourcesPlugin.getWorkspace().getRoot().findContainersForLocation(new Path(selectedFileName));
            if (containers.length > 0) {
                System.out.println("Found container: " + containers[0].getFullPath().toString());
            }
        }
    }
}

afterExample:
package test;

import org.eclipse.core.filesystem.URIUtil;
import org.eclipse.core.resources.IContainer;
import org.eclipse.core.resources.ResourcesPlugin;
import org.eclipse.core.runtime.Path;

public class MyClass {
    public void processFile(String selectedFileName) {
        if (selectedFileName != null) {
            // Modernized usage
            IContainer[] containers = ResourcesPlugin.getWorkspace().getRoot().findContainersForLocationURI(URIUtil.toURI(new Path(selectedFileName).makeAbsolute()));
            if (containers.length > 0) {
                System.out.println("Found container: " + containers[0].getFullPath().toString());
            }
        }
    }
}

